let e={machine:[{label:"设备编号",value:'"{{ machine_id }}"'},{label:"设备名称",value:'"{{ machine_name }}"'},{label:"故障码",value:'"{{ errorCode }}"'},{label:"在线状态",value:'"{{ online }}"'},{label:"最后上线时间点，年-月-日 时:分:秒",value:'"{{ last_online_time }}"'}],geography:[{label:"国家名称",value:'"{{ country }}"'},{label:"州/省",value:'"{{ state }}"'},{label:"城市",value:'"{{ city }}"'},{label:"区域",value:'"{{ regions }}"'},{label:"街道",value:'"{{ street }}"'},{label:"楼层",value:'"{{ floor }}"'}],goods:[{label:"货架编号",value:'"{{ channel_code }}"'},{label:"商品名称",value:'"{{ g_name }}"'},{label:"商品分类",value:'"{{ gc_name }}"'},{label:"账号昵称",value:'"{{ nickname }}"'}],time:[{label:"年",value:'"{{ Y }}"'},{label:"月",value:'"{{ m }}"'},{label:"日",value:'"{{ d }}"'},{label:"时",value:'"{{ H }}"'},{label:"分",value:'"{{ i }}"'},{label:"秒",value:'"{{ s }}"'},{label:"年-月-日",value:'"{{ date }}"'},{label:"时:分:秒",value:'"{{ time }}"'},{label:"现在时间点，年-月-日 时:分:秒",value:'"{{ now }}"'}],order:[{label:"订单编号",value:'"{{ trade_no }}"'},{label:"支付类型",value:'"{{ pay_type }}"'},{label:"支付方式",value:'"{{ pay_method }}"'},{label:"支付状态",value:'"{{ pay_status }}"'},{label:"支付时间，年-月-日 时:分:秒",value:'"{{ pay_time }}"'}]},t=(a,b)=>{let l=[];if(a==1&&(l=[...e.machine,...e.geography,...e.goods,...e.time,...e.order]),a==2)for(let u in e)u==b&&(l=e[u]);return l};const v={exportData:t};export{v as e};
